1	/**
2	 * File Reference Validator
3	 *
4	 * Validates cross-file references in BMAD source files (agents, workflows, tasks, steps).
5	 * Catches broken file paths, missing referenced files, and absolute path leaks.
6	 *
7	 * What it checks:
8	 * - {project-root}/_bmad/ references in YAML and markdown resolve to real src/ files
9	 * - Relative path references (file.md, ../data/file.csv) point to existing files
10	 * - exec="..." and <invoke-task> targets exist
11	 * - Step metadata (thisStepFile, nextStepFile) references are valid
12	 * - Workflow-data frontmatter keys (<name>Data: 'assets/...' or 'references/...')
13	 *   resolved relative to the workflow root (parent of references/) — e.g.
14	 *   assemblyRulesData, skillSectionsData, tesslDismissalData, extractionPatternsData
15	 * - Load directives (Load: `file.md`) target existing files
16	 * - No absolute paths (/Users/, /home/, C:\) leak into source files
17	 *
18	 * What it does NOT check (deferred):
19	 * - {installed_path} variable interpolation (self-referential, low risk)
20	 * - {{mustache}} template variables (runtime substitution)
21	 * - {config_source}:key dynamic YAML dereferences
22	 *
23	 * Usage:
24	 *   node tools/validate-file-refs.js            # Warn on broken references (exit 0)
25	 *   node tools/validate-file-refs.js --strict    # Fail on broken references (exit 1)
26	 *   node tools/validate-file-refs.js --verbose   # Show all checked references
27	 *
28	 * Default mode is warning-only (exit 0) so adoption is non-disruptive.
29	 * Use --strict when you want CI or pre-commit to enforce valid references.
30	 */
31	
32	const fs = require('node:fs');
33	const path = require('node:path');
34	// Dev-only tool — yaml and csv-parse are in devDependencies (runs via npm run quality / CI only)
35	const yaml = require('yaml');
36	const { parse: parseCsv } = require('csv-parse/sync');
37	
38	const PROJECT_ROOT = path.resolve(__dirname, '..');
39	const SRC_DIR = path.join(PROJECT_ROOT, 'src');
40	const VERBOSE = process.argv.includes('--verbose');
41	const STRICT = process.argv.includes('--strict');
42	
43	// --- Constants ---
44	
45	// File extensions to scan
46	const SCAN_EXTENSIONS = new Set(['.yaml', '.yml', '.md', '.xml', '.csv']);
47	
48	// Skip directories
49	const SKIP_DIRS = new Set(['node_modules', '.git', '.analysis']);
50	
51	// Pattern: {project-root}/_bmad/ references
52	const PROJECT_ROOT_REF = /\{project-root\}\/_bmad\/([^\s'"<>})\]`]+)/g;
53	
54	// Pattern: {_bmad}/ shorthand references
55	const BMAD_SHORTHAND_REF = /\{_bmad\}\/([^\s'"<>})\]`]+)/g;
56	
57	// Pattern: exec="..." attributes
58	const EXEC_ATTR = /exec="([^"]+)"/g;
59	
60	// Pattern: <invoke-task> content
61	const INVOKE_TASK = /<invoke-task>([^<]+)<\/invoke-task>/g;
62	
63	// Pattern: relative paths in quotes
64	const RELATIVE_PATH_QUOTED = /['"](\.\.\/?[^'"]+\.(?:md|yaml|yml|xml|json|csv|txt))['"]/g;
65	const RELATIVE_PATH_DOT = /['"](\.\/[^'"]+\.(?:md|yaml|yml|xml|json|csv|txt))['"]/g;
66	
67	// Pattern: step metadata
68	const STEP_META = /(?:thisStepFile|nextStepFile|continueStepFile|skipToStepFile|altStepFile|workflowFile):\s*['"](\.[^'"]+)['"]/g;
69	
70	// Pattern: workflow-data frontmatter keys
71	// Matches any `<name>Data:` frontmatter key with a bare relative path value
72	// (no leading ./ or ../). These paths resolve relative to the workflow root
73	// (parent of references/), not the step file's directory. Used by step files to
74	// reference shared assets like assets/compile-assembly-rules.md or
75	// references/extraction-patterns.md.
76	const WORKFLOW_DATA_REF = /(\w+Data):\s*['"]([^'"./][^'"]*\.(?:md|yaml|yml|json))['"]/g;
77	
78	// Pattern: Load directives
79	const LOAD_DIRECTIVE = /Load[:\s]+`(\.[^`]+)`/g;
80	
81	// Pattern: absolute path leaks
82	const ABS_PATH_LEAK = /(?:\/Users\/|\/home\/|[A-Z]:\\\\)/;
83	
84	// --- Output Escaping ---
85	
86	function escapeAnnotation(str) {
87	  return str.replaceAll('%', '%25').replaceAll('\r', '%0D').replaceAll('\n', '%0A');
88	}
89	
90	function escapeTableCell(str) {
91	  return String(str).replaceAll('|', String.raw`\|`);
92	}
93	
94	// Path prefixes/patterns that only exist in installed structure, not in source.
95	// `agents/` is where bmad-method core agents land under `_bmad/`; referenced by
96	// some workflows (e.g. test-skill's --discovery-catalog=all escape hatch) but
97	// never sourced from this repo.
98	const INSTALL_ONLY_PATHS = ['_config/', '_memory/', 'agents/'];
99	
100	// Files that are generated at install time and don't exist in the source tree
101	const INSTALL_GENERATED_FILES = ['config.yaml', 'config.user.yaml', 'VERSION', 'package.json'];
102	
103	// Variables that indicate a path is not statically resolvable
104	const UNRESOLVABLE_VARS = [
105	  '{output_folder}',
106	  '{value}',
107	  '{timestamp}',
108	  '{config_source}:',
109	  '{installed_path}',
110	  '{shared_path}',
111	  '{planning_artifacts}',
112	  '{research_topic}',
113	  '{user_name}',
114	  '{communication_language}',
115	  '{epic_number}',
116	  '{next_epic_num}',
117	  '{epic_num}',
118	  '{part_id}',
119	  '{count}',
120	  '{date}',
121	  '{outputFile}',
122	  '{nextStepFile}',
123	  '{sidecar_path}',
124	  '{skills_output_folder}',
125	  '{forge_data_folder}',
126	  '{project_name}',
127	  '{document_output_language}',
128	  '{skf_folder}',
129	];
130	
131	// --- File Discovery ---
132	
133	function getSourceFiles(dir) {
134	  const files = [];
135	
136	  function walk(currentDir) {
137	    const entries = fs.readdirSync(currentDir, { withFileTypes: true });
138	
139	    for (const entry of entries) {
140	      if (SKIP_DIRS.has(entry.name)) continue;
141	
142	      const fullPath = path.join(currentDir, entry.name);
143	
144	      if (entry.isDirectory()) {
145	        walk(fullPath);
146	      } else if (entry.isFile() && SCAN_EXTENSIONS.has(path.extname(entry.name))) {
147	        files.push(fullPath);
148	      }
149	    }
150	  }
151	
152	  walk(dir);
153	  return files;
154	}
155	
156	// --- Code Block Stripping ---
157	
158	function stripCodeBlocks(content) {
159	  return content.replaceAll(/```[\s\S]*?```/g, (m) => m.replaceAll(/[^\n]/g, ''));
160	}
161	
162	function stripJsonExampleBlocks(content) {
163	  // Strip bare JSON example blocks: { and } each on their own line.
164	  // These are example/template data (not real file references).
165	  return content.replaceAll(/^\{\s*\n(?:.*\n)*?^\}\s*$/gm, (m) => m.replaceAll(/[^\n]/g, ''));
166	}
167	
168	// --- Path Mapping ---
169	
170	function mapInstalledToSource(refPath) {
171	  // Strip {project-root}/_bmad/ or {_bmad}/ prefix
172	  let cleaned = refPath.replace(/^\{project-root\}\/_bmad\//, '').replace(/^\{_bmad\}\//, '');
173	
174	  // Also handle bare _bmad/ prefix (seen in some invoke-task)
175	  cleaned = cleaned.replace(/^_bmad\//, '');
176	
177	  // Skip install-only paths (generated at install time, not in source)
178	  if (isInstallOnly(cleaned)) return null;
179	
180	  // Map installed module names to their source directory names
181	  // _bmad/skf/ → src/ (SKF module)
182	  if (cleaned.startsWith('skf/')) {
183	    return path.join(SRC_DIR, cleaned.slice('skf/'.length));
184	  }
185	
186	  // Fallback: map directly under src/
187	  return path.join(SRC_DIR, cleaned);
188	}
189	
190	// --- Reference Extraction ---
191	
192	function isResolvable(refStr) {
193	  // Skip refs containing unresolvable runtime variables
194	  if (refStr.includes('{{')) return false;
195	  // Skip node_modules references (runtime dependency paths)
196	  if (refStr.includes('node_modules')) return false;
197	  for (const v of UNRESOLVABLE_VARS) {
198	    if (refStr.includes(v)) return false;
199	  }
200	  return true;
201	}
202	
203	function isInstallOnly(cleanedPath) {
204	  // Skip paths that only exist in the installed _bmad/ structure, not in src/
205	  for (const prefix of INSTALL_ONLY_PATHS) {
206	    if (cleanedPath.startsWith(prefix)) return true;
207	  }
208	  // Skip files that are generated during installation
209	  const basename = path.basename(cleanedPath);
210	  for (const generated of INSTALL_GENERATED_FILES) {
211	    if (basename === generated) return true;
212	  }
213	  return false;
214	}
215	
216	function extractYamlRefs(filePath, content) {
217	  const refs = [];
218	
219	  let doc;
220	  try {
221	    doc = yaml.parseDocument(content);
222	  } catch {
223	    return refs; // Skip unparseable YAML (schema validator handles this)
224	  }
225	
226	  function checkValue(value, range, keyPath) {
227	    if (typeof value !== 'string') return;
228	    if (!isResolvable(value)) return;
229	
230	    const line = range ? offsetToLine(content, range[0]) : undefined;
231	
232	    // Check for {project-root}/_bmad/ refs
233	    const prMatch = value.match(/\{project-root\}\/_bmad\/[^\s'"<>})\]`]+/);
234	    if (prMatch) {
235	      refs.push({ file: filePath, raw: prMatch[0], type: 'project-root', line, key: keyPath });
236	    }
237	
238	    // Check for {_bmad}/ refs
239	    const bmMatch = value.match(/\{_bmad\}\/[^\s'"<>})\]`]+/);
240	    if (bmMatch) {
241	      refs.push({ file: filePath, raw: bmMatch[0], type: 'project-root', line, key: keyPath });
242	    }
243	
244	    // Check for relative paths
245	    const relMatch = value.match(/^\.\.?\/[^\s'"<>})\]`]+\.(?:md|yaml|yml|xml|json|csv|txt)$/);
246	    if (relMatch) {
247	      refs.push({ file: filePath, raw: relMatch[0], type: 'relative', line, key: keyPath });
248	    }
249	  }
250	
251	  function walkNode(node, keyPath) {
252	    if (!node) return;
253	
254	    if (yaml.isMap(node)) {
255	      for (const item of node.items) {
256	        const key = item.key && item.key.value !== undefined ? item.key.value : '?';
257	        const childPath = keyPath ? `${keyPath}.${key}` : String(key);
258	        walkNode(item.value, childPath);
259	      }
260	    } else if (yaml.isSeq(node)) {
261	      for (const [i, item] of node.items.entries()) {
262	        walkNode(item, `${keyPath}[${i}]`);
263	      }
264	    } else if (yaml.isScalar(node)) {
265	      checkValue(node.value, node.range, keyPath);
266	    }
267	  }
268	
269	  walkNode(doc.contents, '');
270	  return refs;
271	}
272	
273	function offsetToLine(content, offset) {
274	  let line = 1;
275	  for (let i = 0; i < offset && i < content.length; i++) {
276	    if (content[i] === '\n') line++;
277	  }
278	  return line;
279	}
280	
281	function extractMarkdownRefs(filePath, content) {
282	  const refs = [];
283	  const stripped = stripJsonExampleBlocks(stripCodeBlocks(content));
284	
285	  function runPattern(regex, type) {
286	    regex.lastIndex = 0;
287	    let match;
288	    while ((match = regex.exec(stripped)) !== null) {
289	      const raw = match[1];
290	      if (!isResolvable(raw)) continue;
291	      refs.push({ file: filePath, raw, type, line: offsetToLine(stripped, match.index) });
292	    }
293	  }
294	
295	  // {project-root}/_bmad/ refs
296	  runPattern(PROJECT_ROOT_REF, 'project-root');
297	
298	  // {_bmad}/ shorthand
299	  runPattern(BMAD_SHORTHAND_REF, 'project-root');
300	
301	  // exec="..." attributes
302	  runPattern(EXEC_ATTR, 'exec-attr');
303	
304	  // <invoke-task> tags
305	  runPattern(INVOKE_TASK, 'invoke-task');
306	
307	  // Step metadata
308	  runPattern(STEP_META, 'relative');
309	
310	  // Workflow-data frontmatter keys — capture the path (group 2, not group 1 which is the key name)
311	  {
312	    WORKFLOW_DATA_REF.lastIndex = 0;
313	    let match;
314	    while ((match = WORKFLOW_DATA_REF.exec(stripped)) !== null) {
315	      const raw = match[2];
316	      if (!isResolvable(raw)) continue;
317	      refs.push({ file: filePath, raw, type: 'workflow-data', line: offsetToLine(stripped, match.index) });
318	    }
319	  }
320	
321	  // Load directives
322	  runPattern(LOAD_DIRECTIVE, 'relative');
323	
324	  // Relative paths in quotes
325	  runPattern(RELATIVE_PATH_QUOTED, 'relative');
326	  runPattern(RELATIVE_PATH_DOT, 'relative');
327	
328	  return refs;
329	}
330	
331	function extractCsvRefs(filePath, content) {
332	  const refs = [];
333	
334	  let records;
335	  try {
336	    records = parseCsv(content, {
337	      columns: true,
338	      skip_empty_lines: true,
339	      relax_column_count: true,
340	    });
341	  } catch (error) {
342	    // No CSV schema validator exists yet (planned as Layer 2c) — surface parse errors visibly.
343	    // YAML equivalent (line ~198) defers to validate-agent-schema.js; CSV has no such fallback.
344	    const rel = path.relative(PROJECT_ROOT, filePath);
345	    console.error(`  [CSV-PARSE-ERROR] ${rel}: ${error.message}`);
346	    if (process.env.GITHUB_ACTIONS) {
347	      console.log(`::warning file=${rel},line=1::${escapeAnnotation(`CSV parse error: ${error.message}`)}`);
348	    }
349	    return refs;
350	  }
351	
352	  // Columns known to contain file path references
353	  const FILE_PATH_COLUMNS = ['workflow-file', 'fragment_file'];
354	
355	  const firstRecord = records[0];
356	  if (!firstRecord) return refs;
357	
358	  // Find which file-path columns exist in this CSV
359	  const activeColumns = FILE_PATH_COLUMNS.filter((col) => col in firstRecord);
360	  if (activeColumns.length === 0) return refs;
361	
362	  for (const [i, record] of records.entries()) {
363	    for (const col of activeColumns) {
364	      const raw = record[col];
365	      if (!raw || raw.trim() === '') continue;
366	      if (!isResolvable(raw)) continue;
367	      // skill: prefixed references are resolved by the IDE/CLI, not as file paths
368	      if (raw.startsWith('skill:')) continue;
369	
370	      // Line = header (1) + data row index (0-based) + 1
371	      const line = i + 2;
372	      refs.push({ file: filePath, raw, type: 'project-root', line });
373	    }
374	  }
375	
376	  return refs;
377	}
378	
379	// --- Reference Resolution ---
380	
381	function resolveRef(ref) {
382	  if (ref.type === 'project-root') {
383	    return mapInstalledToSource(ref.raw);
384	  }
385	
386	  if (ref.type === 'relative') {
387	    return path.resolve(path.dirname(ref.file), ref.raw);
388	  }
389	
390	  if (ref.type === 'workflow-data') {
391	    // Two resolution conventions:
392	    //  1. Bare path starting with a workflow name (e.g., 'skf-create-skill/references/foo.md')
393	    //     → resolve relative to src/ (cross-workflow reference).
394	    //  2. Bare path starting with 'assets/' or 'references/' (or any other directory that is
395	    //     NOT a sibling workflow) → resolve relative to the current workflow root.
396	    const stepParent = path.dirname(ref.file); // src/{workflow}/steps-c
397	    const workflowRoot = path.dirname(stepParent); // src/{workflow}
398	    const firstSegment = ref.raw.split('/')[0];
399	    const crossWorkflowCandidate = path.join(SRC_DIR, firstSegment);
400	    if (firstSegment && fs.existsSync(crossWorkflowCandidate) && fs.statSync(crossWorkflowCandidate).isDirectory()) {
401	      // First segment is a real directory under src/ — treat as cross-workflow reference.
402	      return path.resolve(SRC_DIR, ref.raw);
403	    }
404	    // Default: resolve relative to the current workflow root.
405	    return path.resolve(workflowRoot, ref.raw);
406	  }
407	
408	  if (ref.type === 'exec-attr') {
409	    let execPath = ref.raw;
410	    if (execPath.includes('{project-root}')) {
411	      return mapInstalledToSource(execPath);
412	    }
413	    if (execPath.includes('{_bmad}')) {
414	      return mapInstalledToSource(execPath);
415	    }
416	    if (execPath.startsWith('_bmad/')) {
417	      return mapInstalledToSource(execPath);
418	    }
419	    // Relative exec path
420	    return path.resolve(path.dirname(ref.file), execPath);
421	  }
422	
423	  if (ref.type === 'invoke-task') {
424	    // Extract file path from invoke-task content
425	    const prMatch = ref.raw.match(/\{project-root\}\/_bmad\/([^\s'"<>})\]`]+)/);
426	    if (prMatch) return mapInstalledToSource(prMatch[0]);
427	
428	    const bmMatch = ref.raw.match(/\{_bmad\}\/([^\s'"<>})\]`]+)/);
429	    if (bmMatch) return mapInstalledToSource(bmMatch[0]);
430	
431	    const bareMatch = ref.raw.match(/_bmad\/([^\s'"<>})\]`]+)/);
432	    if (bareMatch) return mapInstalledToSource(bareMatch[0]);
433	
434	    return null; // Can't resolve — skip
435	  }
436	
437	  return null;
438	}
439	
440	// --- Absolute Path Leak Detection ---
441	
442	function checkAbsolutePathLeaks(filePath, content) {
443	  const leaks = [];
444	  const stripped = stripCodeBlocks(content);
445	  const lines = stripped.split('\n');
446	
447	  for (const [i, line] of lines.entries()) {
448	    if (ABS_PATH_LEAK.test(line)) {
449	      leaks.push({ file: filePath, line: i + 1, content: line.trim() });
450	    }
451	  }
452	
453	  return leaks;
454	}
455	
456	// --- Exports (for testing) ---
457	module.exports = { extractCsvRefs };
458	
459	// --- Main ---
460	
461	if (require.main === module) {
462	  console.log(`\nValidating file references in: ${SRC_DIR}`);
463	  console.log(`Mode: ${STRICT ? 'STRICT (exit 1 on issues)' : 'WARNING (exit 0)'}${VERBOSE ? ' + VERBOSE' : ''}\n`);
464	
465	  const files = getSourceFiles(SRC_DIR);
466	  console.log(`Found ${files.length} source files\n`);
467	
468	  let totalRefs = 0;
469	  let brokenRefs = 0;
470	  let totalLeaks = 0;
471	  let filesWithIssues = 0;
472	  const allIssues = []; // Collect for $GITHUB_STEP_SUMMARY
473	
474	  for (const filePath of files) {
475	    const relativePath = path.relative(PROJECT_ROOT, filePath);
476	    const content = fs.readFileSync(filePath, 'utf-8');
477	    const ext = path.extname(filePath);
478	
479	    // Extract references
480	    let refs;
481	    if (ext === '.yaml' || ext === '.yml') {
482	      refs = extractYamlRefs(filePath, content);
483	    } else if (ext === '.csv') {
484	      refs = extractCsvRefs(filePath, content);
485	    } else {
486	      refs = extractMarkdownRefs(filePath, content);
487	    }
488	
489	    // Resolve and classify all refs before printing anything.
490	    // This avoids the confusing pattern of printing headers at two different
491	    // times depending on verbosity — collect first, then print once.
492	    const broken = [];
493	    const ok = [];
494	
495	    for (const ref of refs) {
496	      totalRefs++;
497	      const resolved = resolveRef(ref);
498	
499	      if (resolved && !fs.existsSync(resolved)) {
500	        const hasExt = path.extname(resolved) !== '';
501	        if (!hasExt) {
502	          // Extensionless path that doesn't exist — not a file, not a directory.
503	          // Flag as UNRESOLVED (distinct from BROKEN which means "file with extension not found").
504	          broken.push({ ref, resolved: path.relative(PROJECT_ROOT, resolved), kind: 'unresolved' });
505	          brokenRefs++;
506	          continue;
507	        }
508	        broken.push({ ref, resolved: path.relative(PROJECT_ROOT, resolved), kind: 'broken' });
509	        brokenRefs++;
510	        continue;
511	      }
512	
513	      if (resolved) {
514	        ok.push({ ref, tag: 'OK' });
515	      }
516	    }
517	
518	    // Check absolute path leaks
519	    const leaks = checkAbsolutePathLeaks(filePath, content);
520	    totalLeaks += leaks.length;
521	
522	    // Print results — file header appears once, in one place
523	    const hasFileIssues = broken.length > 0 || leaks.length > 0;
524	
525	    if (hasFileIssues) {
526	      filesWithIssues++;
527	      console.log(`\n${relativePath}`);
528	
529	      if (VERBOSE) {
530	        for (const { ref, tag, note } of ok) {
531	          const suffix = note ? ` (${note})` : '';
532	          console.log(`  [${tag}] ${ref.raw}${suffix}`);
533	        }
534	      }
535	
536	      for (const { ref, resolved, kind } of broken) {
537	        const location = ref.line ? `line ${ref.line}` : ref.key ? `key: ${ref.key}` : '';
538	        const tag = kind === 'unresolved' ? 'UNRESOLVED' : 'BROKEN';
539	        const detail = kind === 'unresolved' ? 'Not found as file or directory' : 'Target not found';
540	        const issueType = kind === 'unresolved' ? 'unresolved path' : 'broken ref';
541	        console.log(`  [${tag}] ${ref.raw}${location ? ` (${location})` : ''}`);
542	        console.log(`     ${detail}: ${resolved}`);
543	        allIssues.push({ file: relativePath, line: ref.line || 1, ref: ref.raw, issue: issueType });
544	        if (process.env.GITHUB_ACTIONS) {
545	          const line = ref.line || 1;
546	          console.log(
547	            `::warning file=${relativePath},line=${line}::${escapeAnnotation(`${tag === 'UNRESOLVED' ? 'Unresolved path' : 'Broken reference'}: ${ref.raw} → ${resolved}`)}`,
548	          );
549	        }
550	      }
551	
552	      for (const leak of leaks) {
553	        console.log(`  [ABS-PATH] Line ${leak.line}: ${leak.content}`);
554	        allIssues.push({ file: relativePath, line: leak.line, ref: leak.content, issue: 'abs-path' });
555	        if (process.env.GITHUB_ACTIONS) {
556	          console.log(`::warning file=${relativePath},line=${leak.line}::${escapeAnnotation(`Absolute path leak: ${leak.content}`)}`);
557	        }
558	      }
559	    } else if (VERBOSE && refs.length > 0) {
560	      console.log(`\n${relativePath}`);
561	      for (const { ref, tag, note } of ok) {
562	        const suffix = note ? ` (${note})` : '';
563	        console.log(`  [${tag}] ${ref.raw}${suffix}`);
564	      }
565	    }
566	  }
567	
568	  // Summary
569	  console.log(`\n${'─'.repeat(60)}`);
570	  console.log(`\nSummary:`);
571	  console.log(`   Files scanned: ${files.length}`);
572	  console.log(`   References checked: ${totalRefs}`);
573	  console.log(`   Broken references: ${brokenRefs}`);
574	  console.log(`   Absolute path leaks: ${totalLeaks}`);
575	
576	  const hasIssues = brokenRefs > 0 || totalLeaks > 0;
577	
578	  if (hasIssues) {
579	    console.log(`\n   ${filesWithIssues} file(s) with issues`);
580	
581	    if (STRICT) {
582	      console.log(`\n   [STRICT MODE] Exiting with failure.`);
583	    } else {
584	      console.log(`\n   Run with --strict to treat warnings as errors.`);
585	    }
586	  } else {
587	    console.log(`\n   All file references valid!`);
588	  }
589	
590	  console.log('');
591	
592	  // Write GitHub Actions step summary
593	  if (process.env.GITHUB_STEP_SUMMARY) {
594	    let summary = '## File Reference Validation\n\n';
595	    if (allIssues.length > 0) {
596	      summary += '| File | Line | Reference | Issue |\n';
597	      summary += '|------|------|-----------|-------|\n';
598	      for (const issue of allIssues) {
599	        summary += `| ${escapeTableCell(issue.file)} | ${issue.line} | ${escapeTableCell(issue.ref)} | ${issue.issue} |\n`;
600	      }
601	      summary += '\n';
602	    }
603	    summary += `**${files.length} files scanned, ${totalRefs} references checked, ${brokenRefs + totalLeaks} issues found**\n`;
604	    fs.appendFileSync(process.env.GITHUB_STEP_SUMMARY, summary);
