export const meta = {
  name: 'skf-skill-quality-analysis',
  description: 'Run the 5 quality-scan lenses over all 16 skf-* skills, then synthesize per-skill findings.json + HTML/MD reports',
  phases: [
    { title: 'Review', detail: '5 lenses/skill: leanness, architecture, determinism, customization, enhancement' },
    { title: 'Synthesis', detail: 'merge lenses -> findings.json + render report per skill' },
  ],
}

const A = args
const B = A.builder
const ref = (f) => `${B}/references/${f}`
const CANON = ref('prompt-quality-canon.md')
const PRINCIPLES = ref('skill-quality-principles.md')
const SCRIPT_STD = ref('script-standards.md')
const SCRIPT_OPPS = ref('script-opportunities-reference.md')
const CUSTOMIZE_GUIDE = ref('customize-toml-guide.md')
const WORKING_STATE = ref('working-state-patterns.md')
const LENS_CONTRACT = ref('lens-contract.md')
const SCAN_ORCH = ref('scan-orchestration.md')
const RENDER = `${B}/scripts/render_report.py`
const SHELL = `${B}/assets/report-shell.html`

const HOUSE = `HOUSE RULES for this repo (bmad-module-skill-forge) — apply BEFORE emitting any finding:
- Run artifacts are NOT skill content: ignore anything under .analysis/, and ignore .memlog.md / .decision-log.md. Never emit a finding about them.
- KNOWN SCANNER FALSE POSITIVES in this repo — do NOT emit findings for these; they are correct-by-design and were verified against CI + the source tree:
  * Bare \`_bmad/custom/<skill>.toml\` refs (no {project-root}/ prefix) in SKILL.md prose are REQUIRED by the CI validate:refs gate; adding {project-root}/ resolves to a nonexistent src/custom/... and BREAKS CI. Correct as-is.
  * Bare \`_bmad/skf/shared/...\` refs shown in prose paired with the dev-checkout \`src/shared/...\` path are intentional dual-mode (installed vs dev) documentation.
  * \`~/\`, \`~\`, \`../\`, and \`../../../etc/passwd\` appearing INSIDE prose/tables as EXAMPLES of accepted input syntax or attack patterns a skill defends against are documentation, not embedded paths.
  * \`~/.skf/workspace/\` as the documented default workspace root is intentional and cross-platform (SKF_WORKSPACE env var takes precedence).
  * \`nextStepFile: '../extract.md'\` step-chain refs are supported by validate:refs and resolve correctly.
  * The workflow-integrity "missing-stage: NN-<name>.md" issues on skf-campaign are a SCANNER BUG: the files exist as references/step-NN-<name>.md and are correctly referenced from SKILL.md. Not a defect.
- SKILL.md token budget for this repo: ~2000 desired, 2500 ceiling. A SKILL.md materially over 2500 is a legitimate finding via your own lane's criteria.
Judge the skill's REAL committed content (SKILL.md, references/, assets/, scripts/, customize.toml, manifest/templates). Report only genuine issues that would survive a real run.`

const LENSES = [
  { name: 'leanness', spec: ref('scan-leanness.md'), loads: [CANON],
    lane: 'whether every present line beats its own absence, and whether what survives reads as a goal rather than a prescription (ceremony, re-teaching native behavior, decorative numbered sequences, ALL-CAPS shouting)' },
  { name: 'architecture', spec: ref('scan-architecture.md'), loads: [CANON, PRINCIPLES],
    lane: 'structure: frontmatter (name+description, two-part trigger format), file topology/carve-out, progressive disclosure, three-mode soundness, and coherence (promises enforced by behavior)' },
  { name: 'determinism', spec: ref('scan-determinism.md'), loads: [SCRIPT_OPPS],
    lane: 'the script-vs-prompt intelligence-placement boundary: intelligence leaks (scripts judging meaning) and determinism leaks (prompts counting/validating/comparing what a script should)' },
  { name: 'customization', spec: ref('scan-customization.md'), loads: [CUSTOMIZE_GUIDE],
    lane: 'customize.toml surface economics (too thin/too loud/merge correctness) and confirming customize.toml is the only config mechanism present' },
  { name: 'enhancement', spec: ref('scan-enhancement.md'), loads: [PRINCIPLES, WORKING_STATE],
    lane: 'missing or over-applied NAMED patterns, working-state strategy for multi-turn builders, and headless readiness' },
]

const LENS_SCHEMA = {
  type: 'object', required: ['lens', 'verdict', 'findings'], additionalProperties: false,
  properties: {
    lens: { type: 'string' },
    verdict: { type: 'string' },
    findings: {
      type: 'array',
      items: {
        type: 'object',
        required: ['id', 'severity', 'title', 'location', 'evidence', 'recommendation'],
        additionalProperties: false,
        properties: {
          id: { type: 'string' },
          severity: { enum: ['critical', 'high', 'medium', 'low'] },
          title: { type: 'string' },
          location: { type: 'string' },
          evidence: { type: 'string' },
          recommendation: { type: 'string' },
          proposed_smallest: { type: 'string' },
          predicted_delta: { type: 'string' },
        },
      },
    },
  },
}

const SUMMARY_SCHEMA = {
  type: 'object', required: ['skill', 'grade', 'verdict', 'counts', 'report_html'], additionalProperties: false,
  properties: {
    skill: { type: 'string' },
    grade: { enum: ['excellent', 'good', 'fair', 'poor'] },
    verdict: { type: 'string' },
    counts: {
      type: 'object', required: ['critical', 'high', 'medium', 'low'], additionalProperties: false,
      properties: { critical: { type: 'integer' }, high: { type: 'integer' }, medium: { type: 'integer' }, low: { type: 'integer' } },
    },
    top_findings: {
      type: 'array',
      items: { type: 'object', additionalProperties: false, properties: { severity: { type: 'string' }, lens: { type: 'string' }, title: { type: 'string' } } },
    },
    primary_strength: { type: 'string' },
    highest_leverage_fix: { type: 'string' },
    report_html: { type: 'string' },
    skill_md_tokens: { type: 'integer' },
  },
}

function lensPrompt(skill, lens) {
  const skillPath = `${A.src}/${skill}`
  const prepass = `${A.prepass}/${skill}.combined.json`
  return `You are the ${lens.name} scan lens reviewing ONE BMad skill: ${skill} at ${skillPath}.

Load these absolute-path files first, then apply their bar (cite their rules, do not restate them):
- Your lens spec (your lane + the tests you run): ${lens.spec}
${lens.loads.map((f) => `- ${f}`).join('\n')}
- Return mechanics: ${LENS_CONTRACT}

Read the pre-pass metrics BEFORE opening raw files; open a raw skill file only for judgment a metric cannot settle:
- Pre-pass JSON (per-file token counts, frontmatter, path/integrity/script scan output): ${prepass}
- Raw skill files live under: ${skillPath}

${HOUSE}

Stay strictly in your lane: ${lens.lane}. Anything another lens owns is out of scope for you.

Return EXACTLY the lens-contract JSON with "lens":"${lens.name}". If the skill passes your lens, return an empty findings array and a verdict saying so. Do NOT pad the list — a weak finding that would not survive a real run is worse than none. The leanness lens (and only it) adds proposed_smallest + predicted_delta on defend-against-absence findings.`
}

function synthPrompt(skill, lenses) {
  const skillPath = `${A.src}/${skill}`
  const runFolder = `${skillPath}/.analysis/${A.ts}`
  return `You are the synthesis layer of the Analyze flow for ONE skill: ${skill} at ${skillPath}.

The 5 lens returns (already lane-filtered and false-positive-aware) are:
${JSON.stringify(lenses)}

Read the synthesis rules + schema (schema_version 2) here — the "Author the synthesis layer", "Schema (schema_version 2)", and "Write and render" sections: ${SCAN_ORCH}

Build the findings.json object (schema_version 2):
- schema_version: 2; subject: "${skillPath}"; generated: "${A.date}".
- findings[]: EVERY lens finding, unchanged — keep each id, lens, severity, title, location, evidence, recommendation. Attach the "lens" field to each finding (its source lens). Keep proposed_smallest/predicted_delta only where the leanness lens supplied them.
- standards: { canon: "${CANON}", principles: "${PRINCIPLES}", scripts: "${SCRIPT_STD}" }.
- verdict: one line naming overall state + the 1-2 findings that matter most.
- grade (lowercase): excellent = no critical AND no high AND few medium; good = some high or several medium; fair = multiple high; poor = any critical.
- summary (2-3 sentences), themes (3-5 by shared root cause; each has title, root_cause, finding_ids[], action), strengths[], recommendations[] (ranked by leverage; each {rank, action, resolves[]}), experience { journeys[], headless }. Omit any optional key entirely rather than writing an empty placeholder. A clean pass is a real report: empty findings[], a grade of excellent, a verdict saying the lenses passed.

Then run these with Bash (do NOT skip; do NOT hand-edit the HTML; do NOT write any memlog):
1. mkdir -p "${runFolder}"
2. Write the findings.json object to "${runFolder}/findings.json" (valid JSON).
3. uv run "${RENDER}" "${runFolder}/findings.json" --shell "${SHELL}" -o "${runFolder}/skill-analysis-report.html" --md "${runFolder}/skill-analysis-report.md"
   If it refuses, fix findings.json and re-run until it renders cleanly.

Finally RETURN the compact summary object (schema-enforced): skill="${skill}"; grade; verdict; counts{critical,high,medium,low} obtained by counting findings[] by severity; top_findings (up to 5 most-severe as {severity,lens,title}); primary_strength (one line drawn from strengths); highest_leverage_fix (the rank-1 recommendation, one line, or "none" if clean); report_html="${runFolder}/skill-analysis-report.html"; skill_md_tokens (integer from the pre-pass metrics skill_md.tokens).`
}

phase('Review')
const summaries = await pipeline(
  A.skills,
  (skill) => parallel(LENSES.map((lens) => () =>
    agent(lensPrompt(skill, lens), { label: `${lens.name}:${skill}`, phase: 'Review', schema: LENS_SCHEMA }),
  )).then((lenses) => ({ skill, lenses: lenses.filter(Boolean) })),
  ({ skill, lenses }) => agent(synthPrompt(skill, lenses), { label: `synth:${skill}`, phase: 'Synthesis', schema: SUMMARY_SCHEMA }),
)
return summaries.filter(Boolean)

